 parts+=['5000 whole-block replicates for origin/year/asset. Full-ledger positive/mean statistics are separate from2010–2024 predictive scores/captures. Bootstrap conditions on frozen fits/oracles and cannot create independent evidence. Cross-asset common shocks and overlapping horizons remain limitations.','## Frozen decision evidence','```json\n'+json.dumps(read('final_decision.json')['gate_evidence'],indent=2)+'\n```','See headroom_decomposition.json for separate perfect, low-dimensional oracle and cross-fit predictable headroom. No favorable subset, amplitude tuning, optional source model or official score re-estimation was performed.','## Baseline protection and provenance',f"Parent RESULT:{PARENT}; parent PRE:{PARENT_PRE}; audit PRE:{verify()['PRE_RESULT_V51_BIAS04_SHA']}; main:{MAIN}. All protected parent Git files and1251 original draw caches remain unchanged. V5.1 Development0.9541 remains the previously verified reference; no submission package is modified. Final RESULT/remote verification/archive hashes are bound by external completion receipt to avoid self-referential commit hashing."]
 execution=OUT/'execution_audit.json'
 if execution.exists():parts+=['## Tests','```json\n'+json.dumps(read('execution_audit.json').get('tests',{}),indent=2)+'\n```']
 (ROOT/'V5.1-CENTER-BIAS-AUDIT-04-report.md').write_text('\n\n'.join(parts)+'\n');status('report','V5.1-CENTER-BIAS-AUDIT-04-report.md')
